    /**
     * Builds the dialog, centered on its owner. It stays hidden until the owner shows it.
     *
     * @param owner window that the dialog blocks while it is open
     */
    AboutDialog(Frame owner, Language language) {
        super(owner, true);
        this.language = language;
        initComponents();
        styleInterface();
        authorContactLabel.putClientProperty(javax.swing.JEditorPane.HONOR_DISPLAY_PROPERTIES, true);
        authorContactLabel.setFont(javax.swing.UIManager.getFont("Label.font"));
        authorContactLabel.setOpaque(false);
        authorContactLabel.setMargin(new java.awt.Insets(0, 0, 0, 0));
        authorContactLabel.setBorder(javax.swing.BorderFactory.createEmptyBorder());
        authorContactLabel.addHyperlinkListener(event -> {
            if (event.getEventType() == HyperlinkEvent.EventType.ACTIVATED) {
                if ("mailto:contact@zlatanstajic.com".equals(event.getDescription())) {
                    openAuthorEmail();
                } else if (AuthorWebsite.URL.equals(event.getDescription())) {
                    openAuthorWebsite();
                }
            }
        });
        getRootPane().setDefaultButton(okButton);
        getRootPane().registerKeyboardAction(event -> dispose(),
                javax.swing.KeyStroke.getKeyStroke("ESCAPE"), javax.swing.JComponent.WHEN_IN_FOCUSED_WINDOW);
        pack();
        java.awt.Rectangle screen = getGraphicsConfiguration().getBounds();
        setMinimumSize(new java.awt.Dimension(360, 280));
        // Allow for Nimbus viewport insets after the first native layout pass.
        setSize(Math.min(Math.max(540, getWidth()), screen.width - 64),
                Math.min(getHeight() + 8, screen.height - 80));
        setLocationRelativeTo(owner);
    }

