    private void styleInterface() {
        ModernTheme.fonts(getContentPane());
        getContentPane().setBackground(ModernTheme.BACKGROUND);
        aboutContentPanel.setBackground(java.awt.Color.WHITE);
        aboutContentPanel.setBorder(javax.swing.BorderFactory.createEmptyBorder(16, 20, 12, 20));
        aboutScrollPane.setBorder(null);
        aboutScrollPane.getVerticalScrollBar().setUnitIncrement(20);
        aboutActionsPanel.setBackground(ModernTheme.BACKGROUND);
        aboutActionsPanel.setBorder(javax.swing.BorderFactory.createEmptyBorder(8, 20, 12, 20));
        ModernTheme.heading(howToSolveHeadingLabel, 1.25f);
        ModernTheme.heading(aboutHeadingLabel, 1.25f);
        ModernTheme.heading(authorHeadingLabel, 1.25f);
        okButton.setBackground(ModernTheme.ACCENT);
        okButton.setForeground(java.awt.Color.WHITE);
    }

    void applyLanguage() {
        language.apply(getContentPane());
        setTitle(language.text("About"));
        revalidate();
    }

    /** Opens the fixed author website and reports launch failures in the chosen language. */
    private void openAuthorWebsite() {
        try {
            AuthorWebsite.open();
        } catch (IOException ex) {
            LOGGER.log(Level.WARNING, "Could not open " + AuthorWebsite.URL, ex);
            JOptionPane.showMessageDialog(this,
                    language.text("Could not open the website. Visit ") + AuthorWebsite.URL
                            + language.text(" in your browser."),
                    language.text("Website"), JOptionPane.ERROR_MESSAGE);
        }
    }

    /** Opens a new message in the desktop's configured email application. */
    private void openAuthorEmail() {
        try {
            AuthorWebsite.openEmail();
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this,
                    language.text("Could not open your email application. Email contact@zlatanstajic.com."),
                    language.text("Email"), JOptionPane.ERROR_MESSAGE);
        }
    }

